/**
 * Download text, binary bytes or text chunks through a Blob URL, then release the temporary URL.
 * Input: downloadFile('id,name\n1,Office', 'data.csv', 'text/csv;charset=utf-8').
 * Output: a browser download named data.csv; no return value.
 */
export function downloadFile(content, filename, type = 'application/geo+json') {
  const url = URL.createObjectURL(new Blob(Array.isArray(content) ? content : [content], { type }))
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.append(link)
  try {
    link.click()
  } finally {
    link.remove()
    // Keep the URL alive until the browser has started reading the download.
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
}
